lder=\"Repeat\"\n  508 |                 value={suConfirm}\n  509 |                 onChange={(e) => setSuConfirm(e.target.value)}\n  510 |                 data-ocid=\"auth.signup.input\"\n  511 |               \/>\n  512 |               {suErrors.confirm && (\n  513 |                 <p className=\"text-xs text-destructive\">{suErrors.confirm}<\/p>\n  514 |               )}\n  515 |             <\/div>\n  516 |           <\/div>\n  517 |           <div className=\"space-y-1.5\">\n  518 |             <Label htmlFor=\"su-degree\">Degree \/ Qualifications<\/Label>\n  519 |             <Input\n  520 |               id=\"su-degree\"\n  521 |               placeholder=\"MBBS, MD, FCPS\"\n  522 |               value={suDegree}\n  523 |               onChange={(e) => setSuDegree(e.target.value)}\n  524 |               data-ocid=\"auth.signup.input\"\n  525 |             \/>\n  526 |           <\/div>\n  527 |           <div className=\"space-y-1.5\">\n  528 |             <Label htmlFor=\"su-spec\">Specialization<\/Label>\n  529 |             <Input\n  530 |               id=\"su-spec\"\n  531 |               value={suSpecialization}\n  532 |               onChange={(e) => setSuSpecialization(e.target.value)}\n  533 |               data-ocid=\"auth.signup.input\"\n  534 |             \/>\n  535 |           <\/div>\n  536 |           <div className=\"space-y-1.5\">\n  537 |             <Label htmlFor=\"su-hospital\">Hospital \/ Clinic<\/Label>\n  538 |             <Input\n  539 |               id=\"su-hospital\"\n  540 |               value={suHospital}\n  541 |               onChange={(e) => setSuHospital(e.target.value)}\n  542 |               data-ocid=\"auth.signup.input\"\n  543 |             \/>\n  544 |           <\/div>\n  545 |           <div className=\"space-y-1.5\">\n  546 |             <Label htmlFor=\"su-phone\">Phone Number<\/Label>\n  547 |             <Input\n  548 |               id=\"su-phone\"\n  549 |               type=\"tel\"\n  550 |               value={suPhone}\n  551 |               onChange={(e) => setSuPhone(e.target.value)}\n  552 |               data-ocid=\"auth.signup.input\"\n  553 |             \/>\n  554 |           <\/div>\n  555 |           <Button\n  556 |             type=\"submit\"\n  557 |             disabled={isLoggingIn}\n  558 |             className=\"w-full h-11 font-semibold mt-1\"\n  559 |             data-ocid=\"auth.signup.submit_button\"\n  560 |           >\n  561 |             {isLoggingIn ? (\n  562 |               <Loader2 className=\"w-4 h-4 mr-2 animate-spin\" \/>\n  563 |             ) : null}\n  564 |             {isLoggingIn ? \"Creating account...\" : \"Create Account\"}\n  565 |           <\/Button>\n  566 |           <p className=\"text-xs text-muted-foreground text-center\">\n  567 |             New accounts require admin approval before login.\n  568 |           <\/p>\n  569 |         <\/form>\n  570 |       <\/TabsContent>\n  571 |     <\/Tabs>\n  572 |   );\n  573 | }\n  574 | \n  575 | \/\/ \u2500\u2500 Patient Auth Content \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  576 | \n  577 | function PatientAuthContent() {\n  578 |   const { patientSignIn, patientSignUp, isLoggingIn, authError } =\n  579 |     useEmailAuth();\n  580 | \n  581 |   const [tab, setTab] = useState(\"signin\");\n  582 |   const [phone, setPhone] = useState(\"\");\n  583 |   const [password, setPassword] = useState(\"\");\n  584 |   const [error, setError] = useState(\"\");\n  585 | \n  586 |   const [suPhone, setSuPhone] = useState(\"\");\n  587 |   const [suPassword, setSuPassword] = useState(\"\");\n  588 |   const [suConfirm, setSuConfirm] = useState(\"\");\n  589 |   const [suRegNo, setSuRegNo] = useState(\"\");\n  590 |   const [suError, setSuError] = useState(\"\");\n  591 |   const [suSuccess, setSuSuccess] = useState(\"\");\n  592 | \n  593 |   const handleSignIn = async (e: React.FormEvent) => {\n  594 |     e.preventDefault();\n  595 |     setError(\"\");\n  596 |     if (!phone || !password) {\n  597 |       setError(\"Please enter phone and password.\");\n  598 |       return;\n  599 |     }\n  600 |     try {\n  601 |       await patientSignIn(phone, password);\n  602 |     } catch (err: unknown) {\n  603 |       setError(err instanceof Error ? err.message : \"Sign in failed.\");\n  604 |     }\n  605 |   };\n  606 | \n  607 |   const handleSignUp = async (e: React.FormEvent) => {\n  608 |     e.preventDefault();\n  609 |     setSuError(\"\");\n  610 |     setSuSuccess(\"\");\n  611 |     if (!suRegNo.trim()) {\n  612 |       setSuError(\n  613 |         \"Register number is required. Contact the clinic to get your register number.\",\n  614 |       );\n  615 |       return;\n  616 |     }\n  617 |     if (!suPhone.trim()) {\n  618 |       setSuError(\"Phone number is required.\");\n  619 |       return;\n  620 |     }\n  621 |     if (!suPassword || suPassword.length < 6) {\n  622 |       setSuError(\"Password must be at least 6 characters.\");\n  623 |       return;\n  624 |     }\n  625 |     if (suPassword !== suConfirm) {\n  626 |       setSuError(\"Passwords do not match.\");\n  627 |       return;\n  628 |     }\n  629 |     try {\n  630 |       await patientSignUp({\n  631 |         registerNumber: suRegNo.trim(),\n  632 |         phone: suPhone.trim(),\n  633 |         password: suPassword,\n  634 |       });\n  635 |     } catch (err: unknown) {\n  636 |       const msg = err instanceof Error ? err.message : \"Sign up failed.\";\n  637 |       if (msg.includes(\"approval\") || msg.includes(\"pending\"))\n  638 |         setSuSuccess(msg);\n  639 |       else setSuError(msg);\n  640 |     }\n  641 |   };\n  642 | \n  643 |   return (\n  644 |     <Tabs value=