\"\n  693 |             disabled={isLoggingIn}\n  694 |             className=\"w-full h-12 text-base font-bold bg-green-600 hover:bg-green-700 shadow-md\"\n  695 |             data-ocid=\"patient_auth.signin.submit_button\"\n  696 |           >\n  697 |             {isLoggingIn ? (\n  698 |               <Loader2 className=\"w-4 h-4 mr-2 animate-spin\" \/>\n  699 |             ) : null}\n  700 |             {isLoggingIn ? \"Signing in...\" : \"Login\"}\n  701 |           <\/Button>\n  702 |           <p className=\"text-center text-sm text-muted-foreground pt-1\">\n  703 |             Don&apos;t have an account?{\" \"}\n  704 |             <button\n  705 |               type=\"button\"\n  706 |               className=\"text-teal-600 underline font-medium\"\n  707 |               onClick={() => setTab(\"signup\")}\n  708 |               data-ocid=\"patient_auth.signup_link.button\"\n  709 |             >\n  710 |               New Account \u2192\n  711 |             <\/button>\n  712 |           <\/p>\n  713 |         <\/form>\n  714 |       <\/TabsContent>\n  715 |       <TabsContent value=\"signup\">\n  716 |         <form onSubmit={handleSignUp} className=\"space-y-3\">\n  717 |           {suError && (\n  718 |             <p\n  719 |               className=\"text-sm text-destructive\"\n  720 |               data-ocid=\"patient_auth.signup.error_state\"\n  721 |             >\n  722 |               {suError}\n  723 |             <\/p>\n  724 |           )}\n  725 |           {suSuccess && (\n  726 |             <div className=\"bg-teal-50 border border-teal-200 rounded-lg px-4 py-3\">\n  727 |               <p className=\"text-sm text-teal-700 font-medium\">{suSuccess}<\/p>\n  728 |             <\/div>\n  729 |           )}\n  730 |           <div\n  731 |             className=\"bg-blue-50 border border-blue-200 rounded-lg px-3 py-2 text-sm text-blue-800\"\n  732 |             data-ocid=\"patient_auth.download_hint\"\n  733 |           >\n  734 |             <