ATES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  977 | \n  978 | const RATES_KEY = \"investigation_rates\";\n  979 | \n  980 | function saveRates(rates: InvestigationRate[]) {\n  981 |   storage.setItem(RATES_KEY, JSON.stringify(rates));\n  982 | }\n  983 | \n  984 | function AdminInvestigationRates() {\n  985 |   const [rates, setRates] = useState<InvestigationRate[]>(() =>\n  986 |     loadInvestigationRates(),\n  987 |   );\n  988 |   const [editingId, setEditingId] = useState<string | null>(null);\n  989 |   const [editName, setEditName] = useState(\"\");\n  990 |   const [editRate, setEditRate] = useState(\"\");\n  991 |   const [editDiscount, setEditDiscount] = useState(\"\");\n  992 |   const [newName, setNewName] = useState(\"\");\n  993 |   const [newRate, setNewRate] = useState(\"\");\n  994 |   const [newDiscount, setNewDiscount] = useState(\"\");\n  995 |   const fileRef = useRef<HTMLInputElement>(null);\n  996 |   const [uploading, setUploading] = useState(false);\n  997 | \n  998 |   function persistRates(updated: InvestigationRate[]) {\n  999 |     setRates(updated);\n 1000 |     saveRates(updated);\n 1001 |   }\n 1002 | \n 1003 |   function handleDelete(id: string) {\n 1004 |     persistRates(rates.filter((r) => r.id !== id));\n 1005 |     toast.success(\"Deleted\");\n 1006 |   }\n 1007 | \n 1008 |   function startEdit(r: InvestigationRate) {\n 1009 |     setEditingId(r.id);\n 1010 |     setEditName(r.name);\n 1011 |     setEditRate(String(r.rate));\n 1012 |     setEditDiscount(String(r.discountRate ?? 0));\n 1013 |   }\n 1014 | \n 1015 |   function saveEdit(id: string) {\n 1016 |     const rateNum = Number(editRate);\n 1017 |     if (!editName.trim() || Number.isNaN(rateNum) || rateNum < 0) {\n 1018 |       toast.error(\"Name and valid rate required\");\n 1019 |       return;\n 1020 |     }\n 1021 |     persistRates(\n 1022 |       rates.map((r) =>\n 1023 |         r.id === id\n 1024 |           ? {\n 1025 |               ...r,\n 1026 |               name: editName.trim(),\n 1027 |               rate: rateNum,\n 1028 |               discountRate: Number(editDiscount) || 0,\n 1029 |             }\n 1030 |           : r,\n 1031 |       ),\n 1032 |     );\n 1033 |     setEditingId(null);\n 1034 |     toast.success(\"Saved\");\n 1035 |   }\n 1036 | \n 1037 |   function handleAddManual() {\n 1038 |     const rateNum = Number(newRate);\n 1039 |     if (!newName.trim() || Number.isNaN(rateNum) || rateNum < 0) {\n 1040 |       toast.error(\"Enter investigation name and rate\");\n 1041 |       return;\n 1042 |     }\n 1043 |     const entry: InvestigationRate = {\n 1044 |       id: Date.now().toString(36) + Math.random().toString(36).slice(2),\n 1045 |       name: newName.trim(),\n 1046 |       rate: rateNum,\n 1047 |       discountRate: Number(newDiscount) || 0,\n 1048 |     };\n 1049 |     persistRates([...rates, entry]);\n 1050 |     setNewName(\"\");\n 1051 |     setNewRate(\"\");\n 1052 |     setNewDiscount(\"\");\n 1053 |     toast.success(\"Investigation added\");\n 1054 |   }\n 1055 | \n 1056 |   function handleExcelUpload(e: React.ChangeEvent<HTMLInputElement>) {\n 1057 |     const file = e.target.files?.[0];\n 1058 |     if (!file) return;\n 1059 |     setUploading(true);\n 1060 | \n 1061 |     const reader = new FileReader();\n 1062 |     reader.onload = async (ev) => {\n 1063 |       try {\n 1064 |         const data = ev.target?.result;\n 1065 |         \/\/ Try SheetJS first, fall back to CSV parsing\n 1066 |         let parsed: { name: string; rate: number }[] = [];\n 1067 | \n 1068 |         if (file.name.endsWith(\".xlsx\") || file.name.endsWith(\".xls\")) {\n 1069 |           \/\/ Excel files cannot be parsed without the xlsx package (not installed).\n 1070 |           \/\/ Instruct the user to save as CSV instead.\n 1071 |           toast.error(\n 1072 |             \"Excel (.xlsx\/.xls) cannot be parsed directly. Please save the file as CSV first (File \u2192 Save As \u2192 CSV), then upload again.\",\n 1073 |           );\n 1074 |           setUploading(false);\n 1075 |           if (fileRef.current) fileRef.current.value = \"\";\n 1076 |           return;\n 1077 |         }\n 1078 |         \/\/ CSV \/ TSV plain-text fallback\n 1079 |         const text =\n 1080 |           typeof data === \"string\"\n 1081 |             ? data\n 1082 |             : new TextDecoder().decode(data as ArrayBuffer);\n 1083 |         const lines = text.split(\/\\r?\\n\/);\n 1084 |         for (const line of lines) {\n 1085 |           const parts = line.split(\/[,\\t]\/);\n 1086 |           const name = (parts[0] ?? \"\").trim();\n 1087 |           const rate = Number((parts[1] ?? \"\").trim());\n 1088 |           if (!name || Number.isNaN(rate) || rate < 0) continue;\n 1089 |           parsed.push({ name, rate });\n 1090 |         }\n 1091 | \n 1092 |         if (parsed.length === 0) {\n 1093 |           toast.error(\n 1094 |             \"No valid rows found. Ensure Column A = Name, Column B = Rate.\",\n 1095 |           );\n 1096 |           setUploading(false);\n 1097 |           return;\n 1098 |         }\n 1099 | \n 1100 |         const newRates: InvestigationRate[] = parsed.map((p) => ({\n 1101 |           id:\n 1102 |             Date.now().toString(36) +\n 1103 |             Math.random().toString(36).slice(2) +\n 1104 |             Math.random().toString(36).slice(2),\n 1105 |           name: p.name,\n 1106 |           rate: p.rate,\n 1107 |           discountRate: 0,\n 1108 |         }));\n 1109 | \n 1110 |         \/\/ Merge: preserve existing entries, add new ones (skip duplicates by name)\n 1111 |         const existingNames = new Set(rates.map((r) => r.name.toLowerCase()));\n 1112 |         const toAdd = newRates.filter(\n 1113 |           (r) => !existingNames.has(r.name.toLowerCase()),\n 1114 |         );\n 1115 |         const merged = [...rates, ...toAdd];\n 1116 |         persistRates(merged);\n 1117 |         toast.success(\n 1118 |           `${toAdd.length} new investigation${toAdd.length !== 1 ? \"s\" : \"\"} loaded (${parsed.length - toAdd.length} skipped as duplicates)`,\n 1119 |         );\n 1120 |       } catch {\n 1121 |         toast.error(\"Failed to parse file\");\n 1122 |       } finally {\n 1123 |         setUploading(false);\n 1124 |         if (fileRef.current) fileRef.current.value = \"\";\n 1125 |       }\n 1126 |     };\n 1127 | \n 1128 |     reader.readAsText(file);\n 1129 |   }\n 1130 | \n 1131 |   return (\n 1132 |     <div className=\"space-y-6\">\n 1133 |       {\/* Upload card *\/}\n 1134 |       <Card>\n 1135 |         <CardHeader className=\"pb-3\">\n 1136 |           <CardTitle className=\"flex items-center gap-2 text-base\">\n 1137 |             <ReceiptText className=\"w-4 h-4 text-purple-600\" \/>\n 1138 |             Investigation Rate List\n 1139 |           <\/CardTitle>\n 1140 |           <CardDescription>\n 1141 |             Upload a CSV file (Column A = Investigation Name, Column B = Rate).\n 1142 |             Existing entries are preserved.\n 1143 |           <\/CardDescription>\n 1144 |         <\/CardHeader>\n 1145 |         <CardContent className=\"space-y-4\">\n 1146 |           <div className=\"flex flex-wrap gap-2 items-center\">\n 1147 |             <Button\n 1148 |               variant=\"outline\"\n 1149 |               className=\"gap-1.5\"\n 1150 |               onClick={() => fileRef.current?.click()}\n 1151 |               disabled={uploading}\n 1152 |               data-ocid=\"admin.inv_rates.upload_button\"\n 1153 |             >\n 1154 |               <Upload className=\"w-4 h-4\" \/>\n 1155 |               {uploading ? \"Parsing\u2026\" : \"Upload CSV File\"}\n 1156 |             <\/Button>\n 1157 |             <sp