Discount}\n 1201 |                 onChange={(e) => setNewDiscount(e.target.value)}\n 1202 |                 className=\"h-8 text-sm\"\n 1203 |                 data-ocid=\"admin.inv_rates.discount.input\"\n 1204 |               \/>\n 1205 |             <\/div>\n 1206 |             <Button\n 1207 |               size=\"sm\"\n 1208 |               className=\"gap-1.5 h-8 shrink-0\"\n 1209 |               onClick={handleAddManual}\n 1210 |               data-ocid=\"admin.inv_rates.add_button\"\n 1211 |             >\n 1212 |               <Plus className=\"w-3.5 h-3.5\" \/>\n 1213 |               Add\n 1214 |             <\/Button>\n 1215 |           <\/div>\n 1216 |         <\/CardContent>\n 1217 |       <\/Card>\n 1218 | \n 1219 |       {\/* Rates table *\/}\n 1220 |       <Card>\n 1221 |         <CardHeader className=\"pb-3\">\n 1222 |           <CardTitle className=\"flex items-center gap-2 text-base\">\n 1223 |             <FlaskConical className=\"w-4 h-4 text-teal-600\" \/>\n 1224 |             Rate List\n 1225 |             {rates.length > 0 && (\n 1226 |               <Badge className=\"bg-purple-100 text-purple-800 border-purple-200 text-xs ml-1\">\n 1227 |                 {rates.length} total\n 1228 |               <\/Badge>\n 1229 |             )}\n 1230 |           <\/CardTitle>\n 1231 |         <\/CardHeader>\n 1232 |         <CardContent>\n 1233 |           {rates.length === 0 ? (\n 1234 |             <p\n 1235 |               className=\"text-sm text-muted-foreground text-center py-8\"\n 1236 |               data-ocid=\"admin.inv_rates.empty_state\"\n 1237 |             >\n 1238 |               No rates configured yet. Upload an Excel file or add manually.\n 1239 |             <\/p>\n 1240 |           ) : (\n 1241 |             <div className=\"rounded-xl border border-border overflow-hidden\">\n 1242 |               <table className=\"w-full text-sm\">\n 1243 |                 <thead>\n 1244 |                   <tr className=\"bg-muted\/50 border-b bor