ave = () => {\n 1832 |     if (!inputUrl.trim()) {\n 1833 |       toast.error(\"Please enter a video URL\");\n 1834 |       return;\n 1835 |     }\n 1836 |     const embed = toEmbedUrl(inputUrl.trim());\n 1837 |     storage.setItem(storageKey, inputUrl.trim());\n 1838 |     \/\/ Broadcast change to other tabs (including SerialDisplay)\n 1839 |     try {\n 1840 |       const bc = new BroadcastChannel(\"serial_display_video_sync\");\n 1841 |       bc.postMessage({ videoUrl: inputUrl.trim() });\n 1842 |       bc.close();\n 1843 |     } catch {}\n 1844 |     setSavedUrl(inputUrl.trim());\n 1845 |     setPreviewUrl(embed);\n 1846 |     setShowPreview(true);\n 1847 |     setInputUrl(\"\");\n 1848 |     toast.success(\"Serial display video URL saved\");\n 1849 |   };\n 1850 | \n 1851 |   const handleClear = () => {\n 1852 |     storage.removeItem(storageKey);\n 1853 |     try {\n 1854 |       const bc = new BroadcastChannel(\"serial_display_video_sync\");\n 1855 |       bc.postMessage({ videoUrl: null });\n 1856 |       bc.close();\n 1857 |     } catch {}\n 1858 |     setSavedUrl(null);\n 1859 |     setPreviewUrl(null);\n 1860 |     setShowPreview(false);\n 1861 |     toast.success(\"Serial display video cleared \u2014 default playlist restored\");\n 1862 |   };\n 1863 | \n 1864 |   return (\n 1865 |     <Card>\n 1866 |       <CardHeader className=\"pb-3\">\n 1867 |         <CardTitle className=\"flex items-center gap-2 text-base\">\n 1868 |           <MonitorPlay className=\"w-4 h-4 text-blue-600\" \/>\n 1869 |           Serial Display Video\n 1870 |         <\/CardTitle>\n 1871 |         <CardDescription>\n 1872 |           Set a custom health education video for the waiting room display\n 1873 |           screen (\n 1874 |           <code className=\"text-xs bg-muted px-1 rounded\">\/serial-display<\/code>\n 1875 |           ). Supports YouTube, Vimeo, or any direct embed URL. Leave blank to\n 1876 |           use the default playlist.\n 1877 |         <\/CardDescriptio